-- ============================ بخش ۱: نگه‌داشتن جدول قدیمی =============

EXEC sp_rename 'dbo.CountryDivisions', 'CountryDivisions_1398';
GO

-- ============================ بخش ۲: جدول نگاشت شناسه‌ها ==============

IF OBJECT_ID('dbo.CountryDivisionIdMap', 'U') IS NOT NULL
    DROP TABLE dbo.CountryDivisionIdMap;
GO

CREATE TABLE dbo.CountryDivisionIdMap (
    OldId           INT           NOT NULL,
    NewId           INT               NULL,
    MatchType       NVARCHAR(8)   NOT NULL,
    OldName         NVARCHAR(150) NOT NULL,
    OldDivisionType TINYINT       NOT NULL,
    CONSTRAINT PK_CountryDivisionIdMap PRIMARY KEY CLUSTERED (OldId)
);
GO

